<form class="card-block stack" method="post" action="<?= e(url('/portal/profile')) ?>"><?= csrf_field() ?><label><?= e(__('fields.name')) ?><input name="name" value="<?= e($user['name']) ?>" required></label><label><?= e(__('fields.phone')) ?><input name="phone" value="<?= e((string) $user['phone']) ?>"></label><label><?= e(__('fields.locale')) ?><select name="locale"><?php foreach ((array) config('app.locales', ['en' => 'English']) as $code => $label): ?><option value="<?= e($code) ?>" <?= selected($user['locale'], $code) ?>><?= e($label) ?></option><?php endforeach; ?></select></label><button class="btn btn-primary" type="submit"><?= e(__('actions.save')) ?></button></form>
<form class="card-block stack" method="post" action="<?= e(url('/portal/profile/password')) ?>"><?= csrf_field() ?><h2><?= e(__('portal.password')) ?></h2><label><?= e(__('fields.current_password')) ?><input type="password" name="current_password" required></label><label><?= e(__('fields.password')) ?><input type="password" name="password" required></label><label><?= e(__('fields.password_confirmation')) ?><input type="password" name="password_confirmation" required></label><button class="btn btn-primary" type="submit"><?= e(__('actions.save')) ?></button></form>
